package main

import (
 "fmt"
 "io"
 "os"
 "strconv"
 "strings"
)

const helpText = `Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
`

type options struct {
 indent, depth int
 color, noColor, tab, html, json, compact, node, inPlace, help, version bool
 xpath, extract, query, attr string
 files []string
}
type flagInfo struct {name, short, kind string}
var flags = []flagInfo{{"attr","a","string"},{"color","c","bool"},{"compact","","bool"},{"depth","d","int"},{"extract","e","string"},{"help","h","bool"},{"html","m","bool"},{"in-place","i","bool"},{"indent","","int"},{"json","j","bool"},{"no-color","","bool"},{"node","n","bool"},{"query","q","string"},{"tab","","bool"},{"version","v","bool"},{"xpath","x","string"}}
func parseArgs(args []string) (o options, err error) {
 o.indent=2;o.depth=-1
 longs:=map[string]flagInfo{}; shorts:=map[string]flagInfo{}
 for _,f:=range flags {longs[f.name]=f; if f.short!=""{shorts[f.short]=f}}
 set:=func(f flagInfo,s string) error {
  var b bool; var n int64; var e error
  if f.kind=="bool" {b,e=strconv.ParseBool(s)} else if f.kind=="int"{n,e=strconv.ParseInt(s,0,64)}
  if e!=nil {label:="--"+f.name;if f.short!=""{label="-"+f.short+", "+label};return fmt.Errorf("invalid argument %q for %q flag: %v",s,label,e)}
  switch f.name {
  case "indent":o.indent=int(n)
  case "depth":o.depth=int(n)
  case "color":o.color=b
  case "no-color":o.noColor=b
  case "compact":o.compact=b
  case "tab":o.tab=b
  case "html":o.html=b
  case "json":o.json=b
  case "node":o.node=b
  case "in-place":o.inPlace=b
  case "help":o.help=b
  case "version":o.version=b
  case "attr":o.attr=s
  case "xpath":o.xpath=s
  case "extract":o.extract=s
  case "query":o.query=s
  }
  return nil
 }
 for i:=0;i<len(args);i++{
  a:=args[i]
  if a=="--"{o.files=append(o.files,args[i+1:]...);break}
  if strings.HasPrefix(a,"--") {
   name,val,has:=strings.Cut(a[2:],"=");f,ok:=longs[name];if !ok{return o,fmt.Errorf("unknown flag: --%s",name)}
   if !has {if f.kind=="bool"{val="true"}else{if i+1==len(args){return o,fmt.Errorf("flag needs an argument: --%s",name)};i++;val=args[i]}}
   if e:=set(f,val);e!=nil{return o,e}
  }else if len(a)>1&&a[0]=='-' {
   for j:=1;j<len(a);j++{
    k:=a[j:j+1];f,ok:=shorts[k];if !ok{return o,fmt.Errorf("unknown shorthand flag: '%s' in %s",k,a)}
    val:="true"
    if j+1<len(a)&&a[j+1]=='=' {val=a[j+2:];j=len(a)}else if f.kind!="bool"{
     if j+1<len(a){val=a[j+1:];j=len(a)}else{if i+1==len(args){return o,fmt.Errorf("flag needs an argument: '%s' in %s",k,a)};i++;val=args[i]}
    }
    if e:=set(f,val);e!=nil{return o,e}
   }
  }else{o.files=append(o.files,a)}
 }
 return o,nil
}
func (o options) indentString() string {if o.tab{return "\t"};return strings.Repeat(" ",max(0,o.indent))}
func errExit(e error,stderr bool) {w:=io.Writer(os.Stdout);if stderr{w=os.Stderr};fmt.Fprintln(w,"Error:",e);os.Exit(1)}
func detect(s string) int {
 if s==""{return 3}
 lower:=strings.ToLower(s)
 if strings.Contains(lower,"<html>")||strings.Contains(lower,"<html ")||strings.Contains(lower,"<html\n")||strings.Contains(lower,"<!doctype"){return 1}
 if strings.Contains(lower,"<?xml"){return 0}
 if strings.ContainsAny(s,"{["){return 2}
 return 0
}
func process(data string,o options)(string,error) {
 if o.xpath!=""||o.extract!="" {return extractXML(data,o)}
 if o.query!="" {return extractCSS(data,o)}
 if o.json {return convertJSON(data,o)}
 typ:=detect(data);if o.html{typ=1}
 switch typ {
 case 0:return formatXML(data,o.indentString(),o.color)
 case 1:return formatHTML(data,o.indentString(),o.color),nil
 case 2:return formatJSON(data,o.indentString(),o.color)
 default:return "",fmt.Errorf("unknown content type: %d",typ)
 }
}
func main(){
 o,e:=parseArgs(os.Args[1:]);if e!=nil{errExit(e,true)}
 if o.help{fmt.Print(helpText);return};if o.version{fmt.Println("xq version 1.4.0");return}
 if o.indent<0||o.indent>8{errExit(fmt.Errorf("indent should be between 0-8 spaces"),true)}
 if o.attr!=""&&o.query==""{errExit(fmt.Errorf("query option (-q) is missed for attribute selection"),true)}
 inputs:=[]*os.File{}
 for _,path:=range o.files{f,e:=os.Open(path);if e!=nil{errExit(e,true)};inputs=append(inputs,f)}
 if o.inPlace&&len(o.files)!=1{errExit(fmt.Errorf("in-place formatting requires a file path (and only one file path)"),true)}
 if len(inputs)==0{inputs=append(inputs,os.Stdin)}
 for i,f:=range inputs{
  data,_:=io.ReadAll(f);if f!=os.Stdin{f.Close()}
  out,e:=process(string(data),o)
  if e!=nil{fmt.Print(out);errExit(e,false)}
  if o.inPlace{if e=os.WriteFile(o.files[i],[]byte(out),0666);e!=nil{errExit(e,true)}}else{fmt.Print(out)}
 }
}
EOF
cat > xml.go <<'EOF'
package main

import (
 "encoding/xml"
 "fmt"
 "io"
 "strings"
 "regexp"
 "bytes"
)

type attr struct {name, value string}
type node struct {kind, name, data string; attrs []attr; children []*node; parent *node}
func addChild(p,n *node){n.parent=p;p.children=append(p.children,n)}
func localName(s string)string{if i:=strings.IndexByte(s,':');i>=0{return s[i+1:]};return s}
func (n *node) attribute(k string)string{for _,a:=range n.attrs{if a.name==k{return a.value}};return ""}
func (n *node) hasAttribute(k string)bool{for _,a:=range n.attrs{if a.name==k{return true}};return false}
func (n *node) text() string {
 switch n.kind {case "text","cdata","attr","comment":return n.data;case "doc","pi","decl":return ""}
 var b strings.Builder;for _,c:=range n.children{if c.kind=="text"||c.kind=="cdata"||c.kind=="element"{b.WriteString(c.text())}};return b.String()
}
func textRecursive(n *node) string {if n.kind=="text"||n.kind=="cdata"{return n.data};var b strings.Builder;for _,c:=range n.children{if c.kind!="comment"{b.WriteString(textRecursive(c))}};return b.String()}
func paint(s string,code int,color bool)string{if color{return fmt.Sprintf("\x1b[%dm%s\x1b[0m",code,s)};return s}
func escapeXML(s string)string{
 var b bytes.Buffer;xml.EscapeText(&b,[]byte(s));v:=b.String();v=strings.ReplaceAll(v,"&#34;","&quot;");v=strings.ReplaceAll(v,"&#39;","&apos;");return v
}
func escapeText(s string)string{r:=strings.NewReplacer("&","&amp;","<","&lt;",">","&gt;");return r.Replace(s)}
func qname(name xml.Name,ns map[string]string)string{
 if name.Space==""{return name.Local};if name.Space=="xmlns"{return "xmlns:"+name.Local}
 if p,ok:=ns[name.Space];ok{if p==""{return name.Local};return p+":"+name.Local}
 return name.Space+":"+name.Local
}
func rawStartName(src string,offset int64)string{
 i:=int(offset);if i>len(src){i=len(src)};i=strings.LastIndex(src[:i],"<");if i<0{return ""};j:=i+1;for j<len(src)&&!strings.ContainsRune(" \t\r\n/>",rune(src[j])){j++};return src[i+1:j]
}
func newXMLDecoder(s string,strict bool)*xml.Decoder{
 d:=xml.NewDecoder(strings.NewReader(s));d.Strict=strict
 d.CharsetReader=func(charset string,in io.Reader)(io.Reader,error){
  b,e:=io.ReadAll(in);if e!=nil{return nil,e};switch strings.ToLower(charset){case "utf-8","utf8","us-ascii","ascii":return bytes.NewReader(b),nil;case "iso-8859-1","latin1","latin-1","windows-1252":var out strings.Builder;for _,v:=range b{out.WriteRune(rune(v))};return strings.NewReader(out.String()),nil};return nil,fmt.Errorf("unsupported charset: %q",charset)
 };return d
}
func parseXML(src string,strict bool)(*node,error){
 doc:=&node{kind:"doc"};stack:=[]*node{doc};ns:=map[string]string{}
 d:=newXMLDecoder(src,strict);count:=0
 for{t,e:=d.Token();if e==io.EOF{break};if e!=nil{return nil,e}
  p:=stack[len(stack)-1]
  switch t:=t.(type){
  case xml.StartElement:
   count++;for _,a:=range t.Attr{if a.Name.Space=="xmlns"{ns[a.Value]=a.Name.Local};if a.Name.Space==""&&a.Name.Local=="xmlns"{ns[a.Value]=""}}
   n:=&node{kind:"element",name:qname(t.Name,ns)}
   if raw:=rawStartName(src,d.InputOffset());raw!=""&&!strings.HasPrefix(raw,"/"){n.name=raw}
   for _,a:=range t.Attr{n.attrs=append(n.attrs,attr{qname(a.Name,ns),a.Value})};addChild(p,n);stack=append(stack,n)
  case xml.EndElement:if len(stack)>1{stack=stack[:len(stack)-1]}
  case xml.CharData:
   s:=string(t);if s!=""{kind:="text";off:=int(d.InputOffset());if off>=3&&off<=len(src)&&strings.HasSuffix(src[:off],"]]>"){kind="cdata"};addChild(p,&node{kind:kind,data:s})}
  case xml.Comment:addChild(p,&node{kind:"comment",data:string(t)})
  case xml.ProcInst:
   kind:="pi";if strings.EqualFold(t.Target,"xml"){kind="decl"}
   addChild(p,&node{kind:kind,name:t.Target,data:string(t.Inst)})
  case xml.Directive:addChild(p,&node{kind:"directive",data:string(t)})
  }
 }
 if count==0{return nil,fmt.Errorf("xmlquery: invalid XML document")};return doc,nil
}
// Text is kept verbatim except for the first line's alignment and trailing spaces.
func alignText(s,indent string,depth int)string{
 s=strings.TrimRight(s," ")
 if p:=strings.IndexByte(s,'\n');p>=0 {
  left:=strings.TrimRight(s[:p]," ")
  right:=strings.TrimLeft(s[p+1:]," ")
  if right!=""&&!strings.HasPrefix(right,"\n") {right=strings.Repeat(indent,max(depth,0))+right}
  s=left+"\n"+right
 }
 return s
}
func formatXML(src,indent string,color bool)(string,error){
 var b strings.Builder;d:=newXMLDecoder(src,false)
 ns:=map[string]string{};names:=[]string{};depth:=0;prev:="";open:=false
 nl:=func(level int){if indent!=""{b.WriteByte('\n');b.WriteString(strings.Repeat(indent,max(0,level)))}}
 closeOpen:=func(){if open{b.WriteString(paint(">",33,color));open=false}}
 for{t,e:=d.Token();if e==io.EOF{break};if e!=nil{return b.String(),e}
  switch t:=t.(type){
  case xml.StartElement:
   closeOpen();if depth>0{nl(depth)}
   for _,a:=range t.Attr{if a.Name.Space=="xmlns"{ns[a.Value]=a.Name.Local};if a.Name.Space==""&&a.Name.Local=="xmlns"{ns[a.Value]=""}}
   name:=qname(t.Name,ns);if raw:=rawStartName(src,d.InputOffset());raw!=""{name=raw}
   names=append(names,name)
   b.WriteString(paint("<"+name,33,color));for _,a:=range t.Attr{b.WriteString(" "+qname(a.Name,ns));b.WriteString(paint("=\""+escapeXML(a.Value)+"\"",32,color))}
   depth++;open=true;prev="start"
  case xml.EndElement:
   depth--;name:=qname(t.Name,ns);if len(names)>0{name=names[len(names)-1];names=names[:len(names)-1]}
   if prev=="start"{b.WriteString(paint("/>",33,color))}else{closeOpen();if prev=="end"{nl(depth)};b.WriteString(paint("</"+name+">",33,color))}
   prev="end";open=false
  case xml.CharData:
   s:=string(t);if strings.TrimSpace(s)==""{continue};closeOpen();s=alignText(s,indent,depth)
   if strings.ContainsAny(s,"<&"){s="<![CDATA["+s+"]]>"}
   b.WriteString(s);prev="text"
  case xml.Comment:
   closeOpen();if depth>0&&prev!="text"{nl(depth)}
   b.WriteString(paint("<!--",94,color)+paint(string(t),94,color)+paint("-->",94,color));if depth==0{nl(0)}
  case xml.ProcInst:
   b.WriteString(paint("<?",33,color)+t.Target)
   fields:=strings.Fields(string(t.Inst))
   for _,v:=range fields{k,val,ok:=strings.Cut(v,"=");if !ok {return b.String(),fmt.Errorf("invalid processing instruction")};val=strings.Trim(val,"\"'");b.WriteString(" "+k+paint("=\""+val+"\"",32,color))}
   b.WriteString(paint("?>",33,color));nl(0)
  case xml.Directive:
   b.WriteString(paint("<!"+string(t)+">",94,color));nl(0)
  }
 }
 return b.String()+"\n",nil
}
func serializeXML(n *node)string{
 var b strings.Builder
 switch n.kind{
 case "doc":for _,c:=range n.children{b.WriteString(serializeXML(c))}
 case "element":b.WriteString("<"+n.name);for _,a:=range n.attrs{b.WriteString(" "+a.name+"=\""+escapeXML(a.value)+"\"")};b.WriteByte('>');for _,c:=range n.children{b.WriteString(serializeXML(c))};b.WriteString("</"+n.name+">")
 case "attr":b.WriteString("<"+n.name+">"+escapeText(n.data)+"</"+n.name+">")
 case "text":b.WriteString(escapeText(n.data))
 case "cdata":b.WriteString("<![CDATA["+n.data+"]]>")
 case "comment":b.WriteString("<!--"+n.data+"-->")
 case "pi","decl":b.WriteString("<?"+n.name);if n.data!=""{b.WriteString(" "+n.data)};b.WriteString("?>")
 case "directive":b.WriteString("<!"+n.data+">")
 }
 return b.String()
}
var _ = regexp.MustCompile
EOF"}

